public abstract class AbstractAnalyzer : Analyzer {
	private string name;
	private AnalyzerType type;
	private string description;
	private bool defaultEnablement = false;
	private bool supportsOneTimeAnalysis;
	private bool isPrototype = false;
	private AnalysisPriority priority = AnalysisPriority.LOW_PRIORITY;
	
	protected static readonly AddressSetView EMPTY_ADDRESS_SET = new AddressSetViewAdapter();

	protected AbstractAnalyzer(string name, string description, AnalyzerType type) {
		this.name = name;
		this.type = type;
		this.description = description;
	}

